// GENERATED by tools/build_pages.py from checkout-test/cart.js: edit that file and run the build, never this copy.
// The site-wide cart: the header's cart link and count, and "Add to cart" on the product pages and the home cards.
// tools/build_pages.py copies this file to /checkout/cart.js (imports pointed at /checkout/lib/); pages load it only
// while CHECKOUT_LIVE = True. The cart lives only in this browser (localStorage, CART_KEY), shared with /checkout/.
// No account, nothing added that the buyer did not press, and every quantity stays inside the Worker's own limits.
//
// "Add to cart" is a plain link to /checkout/?add=CODE: with this script it adds one pack and stays on the page;
// without it (or when the browser will not save), the link opens the checkout, which adds the pack there.
// Its feedback text comes from the button itself (data-added / data-full), written by the build in the page's language.
import { CART_KEY, cartAdd, cartCount } from "./lib/cart-link.js";

const read = () => {
  try {
    const s = JSON.parse(localStorage.getItem(CART_KEY) || "{}");
    return s && typeof s === "object" && !Array.isArray(s) ? s : {};
  } catch { return {}; }
};
const write = (s) => {
  try { localStorage.setItem(CART_KEY, JSON.stringify(s)); return true; } catch { return false; }
};

function paint() {
  const n = cartCount(read().cart);
  document.querySelectorAll("[data-cart-count]").forEach((el) => {
    el.textContent = n ? String(n) : "";
    el.hidden = !n;
  });
}

let live = null; // one polite live region, so screen readers hear "Added to your cart"
function say(text) {
  if (!live) {
    live = document.createElement("p");
    live.className = "cart-live";
    live.setAttribute("role", "status");
    live.setAttribute("aria-live", "polite");
    document.body.appendChild(live);
  }
  live.textContent = "";
  setTimeout(() => { live.textContent = text; }, 60);
}

const labels = new WeakMap();
const timers = new WeakMap();
function flash(a, text) {
  if (!labels.has(a)) labels.set(a, a.innerHTML);
  a.textContent = text;
  a.classList.add("is-added");
  clearTimeout(timers.get(a));
  timers.set(a, setTimeout(() => { a.innerHTML = labels.get(a); a.classList.remove("is-added"); }, 2200));
}

document.addEventListener("click", (e) => {
  const a = e.target.closest && e.target.closest("a[data-cart-add]");
  if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
  const s = read();
  const r = cartAdd(s.cart, a.dataset.cartAdd);
  if (!r.ok) return; // not sold here: the link opens the checkout, which says so
  if (!write({ ...s, cart: r.cart })) return; // storage blocked: the checkout adds it instead
  e.preventDefault();
  paint();
  const text = r.added ? a.dataset.added : a.dataset.full;
  if (text) { flash(a, text); say(text); }
});
window.addEventListener("storage", (e) => { if (e.key === CART_KEY || e.key === null) paint(); });
window.addEventListener("pageshow", paint); // back/forward cache: the count may have changed on another page
paint();
